static int32_t lm_WindowsSystem_shell_4000029(const char* command) {
    size_t n = strlen(command);
    char* quoted = (char*)malloc(n + 3);
    if (quoted == NULL) return -1;
    quoted[0] = '"';
    memcpy(quoted + 1, command, n);
    quoted[n + 1] = '"';
    quoted[n + 2] = 0;
    int r = system(quoted);
    free(quoted);
    return (int32_t)r;
}
